def can_sort(cards):
    # Check if the cards are already sorted
    if cards == 'abc':
        return 'YES'

    # Check if there is exactly one mismatch
    mismatches = 0
    for i in range(3):
        if cards[i] != 'abc'[i]:
            mismatches += 1

    # If there is exactly one mismatch, it means we can swap to sort
    if mismatches == 1:
        return 'YES'

    return 'NO'

